import {analyze} from './engine.js';
import {recoveryPlans} from './recovery.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const samples={bank:'Security alert: Your bank account is at risk. Transfer your money to a safe account now. Do not call your branch.',delivery:'Your parcel could not be delivered. Pay a redelivery fee of $2.99 immediately at https://parcel-check.example to avoid return.',code:'This is account support. Send us your verification code to prevent your account from being suspended.',normal:'Your appointment is tomorrow at 10 AM. If you need to reschedule, use the clinic app you normally use.'};
let current=null,planKey='none';const empty=$('#result').innerHTML;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function page(key){if(!['check','recovery','lab'].includes(key))key='check';$$('.page').forEach(p=>p.hidden=p.id!==`page-${key}`);$$('.nav').forEach(n=>{const active=n.dataset.page===key;n.classList.toggle('active',active);active?n.setAttribute('aria-current','page'):n.removeAttribute('aria-current')});history.replaceState(null,'','#'+key);window.scrollTo(0,0)}
$$('.nav').forEach(n=>n.onclick=()=>page(n.dataset.page));$$('a[href="#check"]').forEach(n=>n.onclick=e=>{e.preventDefault();page('check')});
function resetResult(){current=null;$('#result').classList.remove('has-result');$('#result').innerHTML=empty;}
function update(){const s=$('#message').value;$('#count').textContent=`${s.length.toLocaleString()} / 5,000`;$('#analyze').disabled=!s.trim();resetResult();$$('[data-sample]').forEach(n=>n.classList.toggle('selected',s===samples[n.dataset.sample]));}
$('#message').oninput=update;$$('[data-sample]').forEach(n=>n.onclick=()=>{$('#message').value=samples[n.dataset.sample];update()});$('#clear').onclick=()=>{$('#message').value='';update();planKey='none';renderPlan();toast('Message and analysis cleared.');$('#message').focus()};
function highlight(text,signals){const box=node('div',undefined,'evidence');const ranges=signals.map(s=>[s.start,s.end]).filter(([a,b])=>Number.isInteger(a)&&b>a&&a>=0&&b<=text.length).sort((a,b)=>a[0]-b[0]);const merged=[];for(const r of ranges){const last=merged.at(-1);if(last&&r[0]<=last[1])last[1]=Math.max(last[1],r[1]);else merged.push([...r]);}let pos=0;for(const [a,b]of merged){box.append(document.createTextNode(text.slice(pos,a)),node('mark',text.slice(a,b)));pos=b;}box.append(document.createTextNode(text.slice(pos)));return box;}
$('#analyze').onclick=()=>{const text=$('#message').value;if(!text.trim())return;current=analyze(text);const r=$('#result');r.replaceChildren();r.classList.add('has-result');r.append(node('div','02  YOUR NEXT STEP','step-label'));r.append(node('div',current.level==='high'?'Pause before acting':current.level==='review'?'Worth a closer look':'No strong cues found — still uncertain',`result-status ${current.level}`));r.append(node('h2',current.level==='high'?'Let’s verify this independently.':current.level==='review'?'A few things deserve a check.':'Keep your usual safeguards.','result-title'),node('p',current.summary,'result-summary'),highlight(text,current.signals));const ul=node('ul',undefined,'signal-list');for(const s of current.signals){const li=node('li');li.append(node('strong',s.label),node('span',s.explanation));ul.append(li)}r.append(ul);const next=node('div',undefined,'next-step');next.append(node('p','YOUR SAFER NEXT STEP','eyebrow'),node('p',current.nextSteps[0]||'Verify independently through a company app or contact you already trust.'));const b=node('button','Help me verify →','verify-button');b.onclick=()=>{b.hidden=true;renderVerify(next)};next.append(b);r.append(next);const d=node('details',undefined,'limit-details');d.append(node('summary','How to interpret this result'));const l=node('ul');['Warning level reflects the potential consequences of detected cues, not a probability of fraud.',...current.limitations].forEach(s=>l.append(node('li',s)));d.append(l);r.append(d);toast('Analysis ready. Review your next step.');if(innerWidth<700)r.scrollIntoView({behavior:'smooth',block:'start'});};
function renderVerify(parent){const div=node('div',undefined,'verify-flow');const label=node('label','Who does the message claim to be from?');label.htmlFor='relationship';const select=node('select');select.id='relationship';[['','Choose a category'],['bank','My bank or payment provider'],['delivery','A delivery company'],['account','An account or service I use'],['other','Someone else / I’m not sure']].forEach(([v,t])=>{const o=node('option',t);o.value=v;select.append(o)});const route=node('div',undefined,'verify-route');select.onchange=()=>{route.replaceChildren();if(!select.value)return;const steps={bank:['Use your existing banking app.','Find support inside the app, or use the number printed on your bank card. Do not use contact details from this message.'],delivery:['Check your original order.','Open the retailer’s app or your original order record. Check delivery status through that independent route.'],account:['Open the service independently.','Use the official app you already have or a saved website address. Check your account notifications there.'],other:['Pause the conversation.','Contact the person or organization through a number or channel you already knew before this message. Ask a trusted person for help if unsure.']};const [title,body]=steps[select.value];route.append(node('strong',title),node('p',body));const check=node('label',undefined,'verified-check'),input=node('input');input.type='checkbox';check.append(input,document.createTextNode('I know an independent way to contact them.'));route.append(check);input.onchange=()=>{if(input.checked)toast('Use that trusted channel. PausePoint has not verified the sender.')}};div.append(label,select,route);parent.append(div)}
const choices={none:'I haven’t interacted',clicked:'I clicked a link',credentials:'I shared a password or code',money:'I sent money',identity:'I shared identity information',remote:'I allowed device access'};
for(const [key,title]of Object.entries(choices)){const b=node('button',undefined,'choice');b.dataset.plan=key;b.append(node('span',title),node('span','→'));b.onclick=()=>{planKey=key;renderPlan()};$('#recovery-choices').append(b)}
function renderPlan(){const p=recoveryPlans[planKey];$$('[data-plan]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.plan===planKey)));const box=$('#recovery-detail');box.replaceChildren(node('p','YOUR ACTION PLAN','eyebrow'),node('h2',p.title),node('p',p.intro,'plan-intro'));const ol=node('ol',undefined,'plan-steps');for(const s of p.steps){const li=node('li');li.append(node('h3',s.title),node('p',s.detail));ol.append(li)}box.append(ol);const sources=node('div',undefined,'sources');sources.append(node('p','GUIDANCE FROM OFFICIAL SOURCES'));for(const s of p.sources){const a=node('a',s.label+' ↗');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';sources.append(a)}box.append(sources);const b=node('button','Download this action plan ↓','secondary export');b.onclick=()=>{const content=['PausePoint — Personal action plan',p.title,p.intro,...p.steps.map((s,i)=>`${i+1}. ${s.title}\n${s.detail}`),'Official resources',...p.sources.map(s=>`${s.label}: ${s.url}`),'General U.S. consumer guidance. No guarantee of safety or recovery. No original message included.'].join('\n\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=node('a');a.href=url;a.download='PausePoint-action-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Action plan downloaded. No message text included.')};box.append(b,node('p','Only the guidance is included. Your original message stays out of the file.','export-note'));}
$('#open-recovery').onclick=()=>{page('recovery');renderPlan()};renderPlan();
$('#about-button').onclick=()=>$('#about-dialog').showModal();$('#close-dialog').onclick=()=>$('#about-dialog').close();
$('#run-lab').onclick=async()=>{const b=$('#run-lab');b.disabled=true;try{const response=await fetch($('#evaluation-set').value==='fresh'?'./fresh-cases.json':'./evaluation-cases.json');if(!response.ok)throw Error('Dataset unavailable');const cases=await response.json();const results=cases.map(c=>({...c,result:analyze(c.text)}));const scams=results.filter(c=>c.label==='scam'),legit=results.filter(c=>c.label==='legitimate');const caught=scams.filter(c=>c.result.level!=='unknown').length,fp=legit.filter(c=>c.result.level!=='unknown').length;const box=$('#lab-results');box.replaceChildren();const metrics=node('div',undefined,'metrics');[[`${caught}/${scams.length}`,'Scam cases flagged'],[`${scams.length-caught}`,'Scam cases missed'],[`${fp}/${legit.length}`,'Legitimate cases flagged'],[`${results.filter(c=>c.label==='ambiguous').length}`,'Ambiguous cases, unscored']].forEach(([v,t])=>{const m=node('div',undefined,'metric');m.append(node('strong',v),node('span',t));metrics.append(m)});box.append(metrics,node('p','“Flagged” means high or review. Orange rows expose misses and false alarms. These examples do not estimate real-world accuracy.','legend'));const wrap=node('div',undefined,'table-wrap'),table=node('table'),head=node('thead'),tr=node('tr');['Synthetic message','Expected label','Detector','Outcome'].forEach(x=>tr.append(node('th',x)));head.append(tr);table.append(head);const body=node('tbody');for(const c of results){const flag=c.result.level!=='unknown';const outcome=c.label==='ambiguous'?'Unscored':c.label==='scam'?(flag?'Flagged':'Missed'):(flag?'False alarm':'No warning');const row=node('tr',undefined,['Missed','False alarm'].includes(outcome)?'miss':'');const t=node('td',c.text);t.append(node('small',c.reason));row.append(t,node('td',c.label),node('td',c.result.level),node('td',outcome));body.append(row)}table.append(body);wrap.append(table);box.append(wrap);toast(`${results.length} cases evaluated in your browser.`)}catch(e){toast('Could not load the test cases. Please reload and try again.')}finally{b.disabled=false}};
page(location.hash.slice(1));

window.addEventListener("pageshow",update);
